#!/usr/bin/env bash
# Fail-closed gate for payment release BEFORE production DB migration/deployment.
# Only read trusted, access-controlled production .env generated by deploy.yml.
set -euo pipefail

if [ "$#" -gt 1 ]; then
  echo "Usage: validate-midtrans-release.sh [trusted-env-file]" >&2
  exit 2
fi
if [ "$#" -eq 1 ]; then
  test -f "$1" || { echo "Midtrans gate: missing trusted environment file." >&2; exit 2; }
  set -a
  # The uploaded production .env contains shell-quoted assignments and is
  # operator-controlled; never accept an untrusted path here.
  # shellcheck disable=SC1090
  source "$1"
  set +a
fi

fail() {
  echo "Midtrans release gate: $1" >&2
  exit 1
}
is_boolean() {
  case "$2" in
    true|false) return 0 ;;
    *) fail "$1 must be literal true or false" ;;
  esac
}
on() { [ "${!1:-false}" = "true" ]; }

for flag in \
  MIDTRANS_PAYMENT_ENABLED MIDTRANS_EXPEDITION_ENABLED \
  MIDTRANS_AUTO_REFUND_ENABLED MIDTRANS_AUTO_REFUND_PRODUCTION_ENABLED \
  MIDTRANS_PRODUCTION_RELEASE_APPROVED MIDTRANS_SANDBOX_UAT_APPROVED \
  MIDTRANS_OPERATIONS_APPROVED MIDTRANS_REFUND_UAT_APPROVED \
  MIDTRANS_REFUND_OPERATIONS_APPROVED; do
  is_boolean "$flag" "${!flag:-false}"
done

mode="${MIDTRANS_ENV:-sandbox}"
case "$mode" in
  sandbox|production) ;;
  *) fail "MIDTRANS_ENV must be sandbox or production" ;;
esac

if on MIDTRANS_EXPEDITION_ENABLED && ! on MIDTRANS_PAYMENT_ENABLED; then
  fail "expedition checkout requires the parent payment switch"
fi
if on MIDTRANS_AUTO_REFUND_ENABLED && ! on MIDTRANS_PAYMENT_ENABLED; then
  fail "auto refund requires the parent payment switch"
fi
if on MIDTRANS_AUTO_REFUND_PRODUCTION_ENABLED && ! on MIDTRANS_AUTO_REFUND_ENABLED; then
  fail "the second refund switch requires auto refund to be enabled"
fi

if ! on MIDTRANS_PAYMENT_ENABLED; then
  echo "Midtrans gate: payment, expedition and auto refund are disabled."
  exit 0
fi

[ -n "${MIDTRANS_SERVER_KEY:-}" ] || fail "enabled payment requires a private server key"
[ -n "${MIDTRANS_CLIENT_KEY:-}" ] || fail "enabled payment requires a client key"
[ -n "${CRON_SECRET:-}" ] || fail "enabled payment requires the authenticated reconciliation cron secret"

if [ "$mode" = "sandbox" ]; then
  if on MIDTRANS_AUTO_REFUND_PRODUCTION_ENABLED; then
    fail "production refund override is not valid in sandbox mode"
  fi
  echo "Midtrans gate: sandbox enabled; production funds remain disabled."
  exit 0
fi

# Production is always a separate, operator-attested go-live decision.
on MIDTRANS_PRODUCTION_RELEASE_APPROVED || fail "production requires explicit release approval"
on MIDTRANS_SANDBOX_UAT_APPROVED || fail "production requires merchant sandbox UAT sign-off"
on MIDTRANS_OPERATIONS_APPROVED || fail "production requires operations runbook sign-off"
[[ "${MIDTRANS_RELEASE_EVIDENCE_ID:-}" =~ ^[A-Za-z0-9][A-Za-z0-9_-]{5,79}$ ]] ||
  fail "production requires a valid internal release evidence ID"
[ "${SESSION_COOKIE_SECURE:-}" = "true" ] ||
  fail "production requires secure session cookies"
[[ "${NEXT_PUBLIC_APP_URL:-}" =~ ^https://[^/[:space:]]+ ]] ||
  fail "production requires HTTPS public app URL"
[ -n "${SUPPORT_EMAIL:-}" ] ||
  fail "production requires a configured support email"

if on MIDTRANS_AUTO_REFUND_ENABLED; then
  on MIDTRANS_AUTO_REFUND_PRODUCTION_ENABLED ||
    fail "production auto refund requires a second explicit enablement"
  on MIDTRANS_REFUND_UAT_APPROVED || fail "production auto refund requires refund-specific sandbox UAT approval"
  on MIDTRANS_REFUND_OPERATIONS_APPROVED || fail "production auto refund requires refund operations approval"
fi

echo "Midtrans gate: approved production release configuration; human evidence must be independently reviewed."
